11	)
12	
13	// View is the program's frame. The router is the only place that sets the
14	// terminal state (alternate screen now), the views only provide content.
15	func (a *App) View() tea.View {
16		v := tea.NewView(a.Render())
17		v.AltScreen = true
18		v.ReportFocus = true            // mode 1004: BlurMsg/FocusMsg (DEVDESK-210)
19		if !a.themeDetectionPending() { // an unset background keeps the terminal's own colour readable
20			v.BackgroundColor = terminalBackground(a.colorProfile, theme.ColorBackground)
21		}
22		v.ProgressBar = terminalProgress(a.progress)                 // DEVDESK-211
23		v.WindowTitle = windowTitle(a.currentView, a.currentContext) // DEVDESK-257
24		return v
25	}
26	
27	// Render renders the interface: header, title line, viewport, footer (Rule 124).
28	// An open overlay replaces the whole thing.
29	func (a *App) Render() string {
30		if overlay := a.activeOverlay(); overlay != "" {
31			return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
32				lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
33		}
34	
35		header := a.renderHeader() + "\n" + a.renderTitleLine()
36		body := a.renderBody()
37		footer := a.renderViewFooter()
38		inner := fitHeight(header, body, footer, a.height)
39	
40		placed := lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
41			lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
42		return a.withPalette(placed)
43	}
44	
45	// withPalette draws the open command palette over the final screen. The
46	// composition happens after fitHeight and Place, on exactly height lines of
47	// width cells, so the geometry is in screen rows whatever the view is.
48	func (a *App) withPalette(screen string) string {
49		lines := a.paletteLines()
50		if len(lines) == 0 {
51			return screen
52		}
53		r := a.paletteRect()
54		composed := overlay.Compose(strings.Split(screen, "\n"), lines, r.X, r.Y, a.width)
55		return strings.Join(composed, "\n")
56	}
57	
58	// fitHeight stacks header, body and footer in at most height lines.
59	// lipgloss.Place pads a short block but never crops a tall one, so on a very
60	// small terminal (header 8 + title 1 + the viewport's minimum + footer) the
61	// frame would be taller than the screen. The surplus is taken from the body
62	// first, bottom lines first: the footer carries the messages, so it outranks
63	// viewport rows. If header and footer alone are taller than the terminal, the
64	// stack is cut to its first height lines, the simplest floor. At normal
65	// heights nothing is cut.
66	func fitHeight(header, body, footer string, height int) string {
67		parts := []string{header}
68		if body != "" {
69			parts = append(parts, body)
70		}
71		if footer != "" {
72			parts = append(parts, footer)
73		}
74		lines := strings.Split(strings.Join(parts, "\n"), "\n")
75		excess := len(lines) - height
76		if height <= 0 || excess <= 0 {
77			return strings.Join(lines, "\n")
78		}
79	
80		headerLen := strings.Count(header, "\n") + 1
81		bodyLen := 0
82		if body != "" {
83			bodyLen = strings.Count(body, "\n") + 1
84		}
85		cut := min(excess, bodyLen)
86		if cut > 0 {
87			end := headerLen + bodyLen
88			lines = append(lines[:end-cut], lines[end:]...)
89		}
90		if len(lines) > height {
91			lines = lines[:height]
92		}
93		return strings.Join(lines, "\n")
94	}
95	
96	// activeOverlay returns the overlay to draw instead of the view, or "" when
97	// there is none. The order matches the one handleKeyMsg dispatches in, so the
98	// overlay holding the keyboard is the one on screen.
99	func (a *App) activeOverlay() string {
100		switch {
101		case a.switchingTo != "":
102			return a.renderContextSwitchingOverlay()
103		case a.showHelp:
104			return a.renderHelpOverlay()
105		case a.showContextList:
106			return a.renderContextListOverlay()
107		}
108		return ""
109	}
110	
111	// renderBody fills the viewport with the active view's content, padded to the
112	// full inner width so no line shows the terminal's own background (Rule 115).
113	func (a *App) renderBody() string {
114		content := "View not found: " + string(a.currentView)
115		if view, ok := a.views[a.currentView]; ok {
116			content = view.Render()
117		}
118	
119		innerWidth := a.viewport.Width() - 2 // -2 for the borders
120		if a.frameless() {
121			innerWidth = a.viewport.Width()
122		}
123		a.viewport.SetContent(lipgloss.NewStyle().
124			Background(theme.ColorBackground).
125			Foreground(theme.ColorText).
126			Width(innerWidth).
127			Render(content))
128	
129		body := a.viewport.View()
130	
131		// Rule 136: with a filter bar below it, the viewport's bottom corners become
132		// T-junctions so the two form one closed rectangle.
133		if view, ok := a.views[a.currentView]; ok {
134			if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
135				body = replaceViewportBottomCorners(body)
136			}
137		}
138		return body
139	}
140	
141	// renderTitleLine draws the viewport's top border carrying the view's title —
142	// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
143	// reader oriented where a top border would draw the top of a nonexistent box.
144	func (a *App) renderTitleLine() string {
145		title := ""
146		if view, ok := a.views[a.currentView]; ok {
147			if hv, implements := view.(HeaderView); implements {
148				title = hv.GetTitle()
149			}
150		}
151		if a.frameless() {
152			return theme.RenderTitledRule(title, a.width)
153		}
154		return theme.RenderBorderTitleTrail(title, a.frameTrail(title), a.width)
155	}
156	
157	// frameTrail asks the active view for its border trail, within the budget the
158	// theme leaves after title. It returns "" when there is no room, the view has
159	// no trail, or the trail is wider than its budget.
160	func (a *App) frameTrail(title string) string {
161		view, ok := a.views[a.currentView]
162		if !ok {
163			return ""
164		}
165		tv, ok := view.(FrameTrailView)
166		if !ok {
167			return ""
168		}
169		budget := theme.BorderTrailBudget(title, a.width)
170		if budget <= 0 {
171			return ""
172		}
173		trail := tv.FrameTrail(budget)
174		if lipgloss.Width(trail) > budget {
175			return ""
176		}
177		return trail
178	}
179	
180	// frameless reports whether the active view draws its own frames (see
181	// FramelessView). The default is framed.
182	func (a *App) frameless() bool {
183		view, ok := a.views[a.currentView]
184		if !ok {
185			return false
186		}
187		fv, implements := view.(FramelessView)
188		return implements && fv.Frameless()
189	}
190	
191	// renderViewFooter returns the active view's footer, or "" when it has none.
192	func (a *App) renderViewFooter() string {
193		if view, ok := a.views[a.currentView]; ok {
194			if fv, ok := view.(FooterView); ok {
195				return fv.RenderFooter(a.width)
196			}
197		}
198		return ""
199	}
200	
201	// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
202	// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
203	// the border into one closed rectangle instead of two stacked boxes.
204	func replaceViewportBottomCorners(body string) string {
205		lastNewline := strings.LastIndex(body, "\n")
206		if lastNewline == -1 {
207			return body
208		}
209		lastLine := body[lastNewline+1:]
210		lastLine = strings.Replace(lastLine, "└", "├", 1)
211		lastLine = strings.Replace(lastLine, "┘", "┤", 1)
212		return body[:lastNewline+1] + lastLine
213	}
