package app

import (
	"strings"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/ui/overlay"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// View is the program's frame. The router is the only place that sets the
// terminal state (alternate screen now), the views only provide content.
func (a *App) View() tea.View {
	v := tea.NewView(a.Render())
	v.AltScreen = true
	v.ReportFocus = true            // mode 1004: BlurMsg/FocusMsg (DEVDESK-210)
	if !a.themeDetectionPending() { // an unset background keeps the terminal's own colour readable
		v.BackgroundColor = terminalBackground(a.colorProfile, theme.ColorBackground)
	}
	v.ProgressBar = terminalProgress(a.progress)                 // DEVDESK-211
	v.WindowTitle = windowTitle(a.currentView, a.currentContext) // DEVDESK-257
	return v
}

// Render renders the interface: header, title line, viewport, footer (Rule 124).
// An open overlay replaces the whole thing.
func (a *App) Render() string {
	if overlay := a.activeOverlay(); overlay != "" {
		return lipgloss.Place(a.width, a.height, lipgloss.Center, lipgloss.Center, overlay,
			lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
	}

	header := a.renderHeader() + "\n" + a.renderTitleLine()
	body := a.renderBody()
	footer := a.renderViewFooter()
	inner := fitHeight(header, body, footer, a.height)

	placed := lipgloss.Place(a.width, a.height, lipgloss.Left, lipgloss.Top, inner,
		lipgloss.WithWhitespaceStyle(lipgloss.NewStyle().Background(theme.ColorBackground)))
	return a.withPalette(placed)
}

// withPalette draws the open command palette over the final screen. The
// composition happens after fitHeight and Place, on exactly height lines of
// width cells, so the geometry is in screen rows whatever the view is.
func (a *App) withPalette(screen string) string {
	lines := a.paletteLines()
	if len(lines) == 0 {
		return screen
	}
	r := a.paletteRect()
	composed := overlay.Compose(strings.Split(screen, "\n"), lines, r.X, r.Y, a.width)
	return strings.Join(composed, "\n")
}

// fitHeight stacks header, body and footer in at most height lines.
// lipgloss.Place pads a short block but never crops a tall one, so on a very
// small terminal (header 8 + title 1 + the viewport's minimum + footer) the
// frame would be taller than the screen. The surplus is taken from the body
// first, bottom lines first: the footer carries the messages, so it outranks
// viewport rows. If header and footer alone are taller than the terminal, the
// stack is cut to its first height lines, the simplest floor. At normal
// heights nothing is cut.
func fitHeight(header, body, footer string, height int) string {
	parts := []string{header}
	if body != "" {
		parts = append(parts, body)
	}
	if footer != "" {
		parts = append(parts, footer)
	}
	lines := strings.Split(strings.Join(parts, "\n"), "\n")
	excess := len(lines) - height
	if height <= 0 || excess <= 0 {
		return strings.Join(lines, "\n")
	}

	headerLen := strings.Count(header, "\n") + 1
	bodyLen := 0
	if body != "" {
		bodyLen = strings.Count(body, "\n") + 1
	}
	cut := min(excess, bodyLen)
	if cut > 0 {
		end := headerLen + bodyLen
		lines = append(lines[:end-cut], lines[end:]...)
	}
	if len(lines) > height {
		lines = lines[:height]
	}
	return strings.Join(lines, "\n")
}

// activeOverlay returns the overlay to draw instead of the view, or "" when
// there is none. The order matches the one handleKeyMsg dispatches in, so the
// overlay holding the keyboard is the one on screen.
func (a *App) activeOverlay() string {
	switch {
	case a.switchingTo != "":
		return a.renderContextSwitchingOverlay()
	case a.showHelp:
		return a.renderHelpOverlay()
	case a.showContextList:
		return a.renderContextListOverlay()
	}
	return ""
}

// renderBody fills the viewport with the active view's content, padded to the
// full inner width so no line shows the terminal's own background (Rule 115).
func (a *App) renderBody() string {
	content := "View not found: " + string(a.currentView)
	if view, ok := a.views[a.currentView]; ok {
		content = view.Render()
	}

	innerWidth := a.viewport.Width() - 2 // -2 for the borders
	if a.frameless() {
		innerWidth = a.viewport.Width()
	}
	a.viewport.SetContent(lipgloss.NewStyle().
		Background(theme.ColorBackground).
		Foreground(theme.ColorText).
		Width(innerWidth).
		Render(content))

	body := a.viewport.View()

	// Rule 136: with a filter bar below it, the viewport's bottom corners become
	// T-junctions so the two form one closed rectangle.
	if view, ok := a.views[a.currentView]; ok {
		if fbv, ok := view.(FilterBarView); ok && fbv.FilterBarVisible() {
			body = replaceViewportBottomCorners(body)
		}
	}
	return body
}

// renderTitleLine draws the viewport's top border carrying the view's title —
// or, for a frameless view, a titled rule with no corners: GetTitle() keeps a
// reader oriented where a top border would draw the top of a nonexistent box.
func (a *App) renderTitleLine() string {
	title := ""
	if view, ok := a.views[a.currentView]; ok {
		if hv, implements := view.(HeaderView); implements {
			title = hv.GetTitle()
		}
	}
	if a.frameless() {
		return theme.RenderTitledRule(title, a.width)
	}
	return theme.RenderBorderTitleTrail(title, a.frameTrail(title), a.width)
}

// frameTrail asks the active view for its border trail, within the budget the
// theme leaves after title. It returns "" when there is no room, the view has
// no trail, or the trail is wider than its budget.
func (a *App) frameTrail(title string) string {
	view, ok := a.views[a.currentView]
	if !ok {
		return ""
	}
	tv, ok := view.(FrameTrailView)
	if !ok {
		return ""
	}
	budget := theme.BorderTrailBudget(title, a.width)
	if budget <= 0 {
		return ""
	}
	trail := tv.FrameTrail(budget)
	if lipgloss.Width(trail) > budget {
		return ""
	}
	return trail
}

// frameless reports whether the active view draws its own frames (see
// FramelessView). The default is framed.
func (a *App) frameless() bool {
	view, ok := a.views[a.currentView]
	if !ok {
		return false
	}
	fv, implements := view.(FramelessView)
	return implements && fv.Frameless()
}

// renderViewFooter returns the active view's footer, or "" when it has none.
func (a *App) renderViewFooter() string {
	if view, ok := a.views[a.currentView]; ok {
		if fv, ok := view.(FooterView); ok {
			return fv.RenderFooter(a.width)
		}
	}
	return ""
}

// replaceViewportBottomCorners turns the viewport's bottom └ and ┘ into the
// T-junctions ├ and ┤, so the filter bar rendered below it in the footer joins
// the border into one closed rectangle instead of two stacked boxes.
func replaceViewportBottomCorners(body string) string {
	lastNewline := strings.LastIndex(body, "\n")
	if lastNewline == -1 {
		return body
	}
	lastLine := body[lastNewline+1:]
	lastLine = strings.Replace(lastLine, "└", "├", 1)
	lastLine = strings.Replace(lastLine, "┘", "┤", 1)
	return body[:lastNewline+1] + lastLine
}

package app

import (
	"fmt"
	"os"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"
	"github.com/charmbracelet/colorprofile"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Measurement of the renderer's output cost (DEVDESK-139, criterion 8). Opt-in:
// it takes about a minute and measures wall-clock rates, so it never runs in CI.
//
//	DEVDESK_MEASURE_REDRAW=1 go test ./internal/app/ -run TestMeasureRedrawCost -v -count=1

const (
	measureWidth    = 120
	measureHeight   = 40
	measureWarmUp   = 2 * time.Second
	measureWindow   = 6 * time.Second
	measureRowWidth = measureWidth - 4
)

// countingWriter is the program's output: it counts what the renderer writes
// and keeps nothing. There is no TTY behind it.
type countingWriter struct{ n, writes atomic.Int64 }

func (w *countingWriter) Write(p []byte) (int, error) {
	w.n.Add(int64(len(p)))
	w.writes.Add(1)
	return len(p), nil
}

// timedProgramModel is programModel with a timed View: the program calls View
// after every Update, so the mean View time is the cost of preparing a redraw.
// The counters are atomics because the test reads them from another goroutine.
type timedProgramModel struct {
	app   *App
	calls *atomic.Int64
	nanos *atomic.Int64
}

func (m timedProgramModel) Init() tea.Cmd { return nil }
func (m timedProgramModel) View() tea.View {
	start := time.Now()
	s := m.app.View()
	m.nanos.Add(int64(time.Since(start)))
	m.calls.Add(1)
	return s
}
func (m timedProgramModel) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	_, cmd := m.app.Update(msg)
	return m, cmd
}

// redrawStats are the figures of one window.
type redrawStats struct {
	bytesPerSec, redrawsPerSec, bytesPerRedraw float64
	viewCalls                                  int64
	meanView                                   time.Duration
	window                                     time.Duration
}

// measuredView draws `rows` lines whose first glyph depends on the animation:
// the blink phase. The
// state is only written from Update, which the program calls from one goroutine.
type measuredView struct {
	fakeView
	rows  int
	blink bool // WantsBlink
	phase bool
}

func (v *measuredView) WantsBlink() bool { return v.blink }

func (v *measuredView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	if f, ok := msg.(jobs.FrameMsg); ok {
		v.phase = f.Blink
	}
	return v, nil
}

func (v *measuredView) View() tea.View { return tea.NewView(v.Render()) }

func (v *measuredView) Render() string {
	glyph := "○"
	if v.phase {
		glyph = "●"
	}
	lines := make([]string, 0, measureHeight)
	for i := 0; i < measureHeight-14; i++ {
		text := fmt.Sprintf("row %02d  some name that stays the same", i)
		if i < v.rows {
			text = glyph + " " + text
		} else {
			text = "  " + text
		}
		lines = append(lines, text+strings.Repeat(" ", max(measureRowWidth-len(text), 0)))
	}
	return strings.Join(lines, "\n")
}

// measureRedraws runs the real router under a tea.Program for the warm-up,
// then measures what is written and how long View takes during the window.
// A redraw is one Write: the renderer flushes once per frame.
func measureRedraws(t *testing.T, view *measuredView) redrawStats {
	t.Helper()
	a := routerAt(t, view, measureWidth, measureHeight)
	out := &countingWriter{}
	var calls, nanos atomic.Int64
	p := tea.NewProgram(timedProgramModel{app: a, calls: &calls, nanos: &nanos},
		tea.WithInput(nil), tea.WithOutput(out), tea.WithoutSignalHandler(),
		// With no TTY, v2 sends its own 0x0 WindowSizeMsg at start-up, which
		// would shrink the router to a stub view; this fixes the size instead.
		tea.WithWindowSize(measureWidth, measureHeight),
		// Output is not a terminal, so v2 would drop colour; force TrueColor to
		// match the DEVDESK-200 v1 reference, which was forced to TrueColor.
		tea.WithColorProfile(colorprofile.TrueColor))

	done := make(chan error, 1)
	go func() { _, err := p.Run(); done <- err }()
	// A key press makes the router ask the view whether it wants a blink.
	p.Send(testutil.Key("down"))

	time.Sleep(measureWarmUp)
	b0, w0, c0, n0, from := out.n.Load(), out.writes.Load(), calls.Load(), nanos.Load(), time.Now()
	time.Sleep(measureWindow)
	bytes, writes := out.n.Load()-b0, out.writes.Load()-w0
	viewCalls, viewNanos, elapsed := calls.Load()-c0, nanos.Load()-n0, time.Since(from)

	p.Quit()
	select {
	case err := <-done:
		if err != nil {
			t.Fatalf("program: %v", err)
		}
	case <-time.After(5 * time.Second):
		t.Fatal("the program did not exit")
	}
	st := redrawStats{
		bytesPerSec:   float64(bytes) / elapsed.Seconds(),
		redrawsPerSec: float64(writes) / elapsed.Seconds(),
		viewCalls:     viewCalls,
		window:        elapsed,
	}
	if writes > 0 {
		st.bytesPerRedraw = float64(bytes) / float64(writes)
	}
	if viewCalls > 0 {
		st.meanView = time.Duration(viewNanos / viewCalls)
	}
	return st
}

// TestMeasureRedrawCost logs the bytes per second the renderer writes for N
// animated rows: 0, 1 and 20 blinking at 1 Hz. Opt-in: DEVDESK_MEASURE_REDRAW=1.
func TestMeasureRedrawCost(t *testing.T) {
	if os.Getenv("DEVDESK_MEASURE_REDRAW") != "1" {
		t.Skip("set DEVDESK_MEASURE_REDRAW=1 to measure the renderer's output")
	}
	cases := []struct {
		mode  string
		rows  int
		hz    int
		blink bool
	}{
		{"blink", 0, 0, false},
		{"blink", 1, 1, true},
		{"blink", 20, 1, true},
	}
	for _, c := range cases {
		t.Run(fmt.Sprintf("%s-%d", c.mode, c.rows), func(t *testing.T) {
			v := &measuredView{rows: c.rows, blink: c.blink}
			st := measureRedraws(t, v)
			t.Logf("rows=%d mode=%s rate=%dHz terminal=%dx%d window=%s bytes/s=%.0f redraws/s=%.2f bytes/redraw=%.0f view=%.1fµs (%d calls)",
				c.rows, c.mode, c.hz, measureWidth, measureHeight, st.window.Round(time.Millisecond),
				st.bytesPerSec, st.redrawsPerSec, st.bytesPerRedraw,
				float64(st.meanView.Nanoseconds())/1000, st.viewCalls)
			// Only a broken counter would record zeros; the figures themselves
			// are wall-clock and asserted nowhere.
			if c.blink && c.rows == 20 && (st.redrawsPerSec <= 0 || st.viewCalls == 0) {
				t.Fatalf("no redraw counted: %+v", st)
			}
		})
	}
}

